import{_ as e}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as r,o as d,af as a}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const g=JSON.parse('{"title":"Kimi 对话与 Agent 速查表","description":"只查不学。入口、斜杠、额度只抄能打开的官方页。两套套餐名不合并。","frontmatter":{"title":"Kimi 对话与 Agent 速查表","description":"只查不学。入口、斜杠、额度只抄能打开的官方页。两套套餐名不合并。","domain":"product","tags":["chat"],"role":"cheatsheet"},"headers":[],"relativePath":"zh/products/kimi/kimi-cheatsheet.md","filePath":"zh/products/kimi/kimi-cheatsheet.md","lastUpdated":1787107158000}'),o={name:"zh/products/kimi/kimi-cheatsheet.md"};function h(i,t,l,n,s,m){return d(),r("div",null,[...t[0]||(t[0]=[a('<h1 id="kimi-对话与-agent-速查表" tabindex="-1">Kimi 对话与 Agent 速查表 <a class="header-anchor" href="#kimi-对话与-agent-速查表" aria-label="Permalink to &quot;Kimi 对话与 Agent 速查表&quot;">​</a></h1><p>只查不学。数字以链出的官方页为准。最后核实：2026-08-19。</p><p>本表<strong>不含</strong> Kimi Code CLI。编码命令见 <a href="/zh/products/kimi-code/">Kimi Code</a>。</p><h2 id="官方入口" tabindex="-1">官方入口 <a class="header-anchor" href="#官方入口" aria-label="Permalink to &quot;官方入口&quot;">​</a></h2><table tabindex="0"><thead><tr><th>面</th><th>入口</th></tr></thead><tbody><tr><td>工作台 / 对话</td><td><a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a></td></tr><tr><td>产品家族</td><td><a href="https://www.kimi.com/zh-cn/products/" target="_blank" rel="noreferrer">kimi.com/zh-cn/products</a></td></tr><tr><td>Agent</td><td><a href="https://www.kimi.com/agent" target="_blank" rel="noreferrer">kimi.com/agent</a></td></tr><tr><td>Agent Swarm</td><td><a href="https://www.kimi.com/agent-swarm" target="_blank" rel="noreferrer">kimi.com/agent-swarm</a></td></tr><tr><td>Kimi Claw</td><td><a href="https://www.kimi.com/bot" target="_blank" rel="noreferrer">kimi.com/bot</a></td></tr><tr><td>Kimi Work（另产品）</td><td><a href="https://www.kimi.com/products/kimi-work" target="_blank" rel="noreferrer">kimi.com/products/kimi-work</a></td></tr><tr><td>Kimi Code（另产品）</td><td><a href="/zh/products/kimi-code/">Kimi Code</a></td></tr><tr><td>API（另产品）</td><td><a href="https://platform.moonshot.cn/" target="_blank" rel="noreferrer">platform.moonshot.cn</a></td></tr><tr><td>帮助中心</td><td><a href="https://www.kimi.com/zh-hans/help" target="_blank" rel="noreferrer">zh-hans/help</a>、<a href="https://www.kimi.com/help" target="_blank" rel="noreferrer">help</a></td></tr><tr><td>公司站 / App</td><td><a href="https://www.moonshot.cn/" target="_blank" rel="noreferrer">moonshot.cn</a></td></tr></tbody></table><p>首页侧栏原文：<a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a> — Plugins、Scheduled Tasks、Slides、Swarm、Deep Research、Docs、Websites、Sheets、Design；Kimi Work、Kimi Code、Kimi Claw。新对话：<strong>⌘K</strong>。</p><p>App 切模型（<a href="https://www.kimi.com/zh-cn/help/agent/agent-overview" target="_blank" rel="noreferrer">Agent 概览</a>）：<strong>K3</strong> 或 <strong>K3 集群 / K3 Swarm</strong>。</p><h2 id="网页里能抄的命令-入口" tabindex="-1">网页里能抄的命令 / 入口 <a class="header-anchor" href="#网页里能抄的命令-入口" aria-label="Permalink to &quot;网页里能抄的命令 / 入口&quot;">​</a></h2><p>这些出现在官方帮助，<strong>不是</strong> Kimi Code TUI。</p><table tabindex="0"><thead><tr><th>输入或按钮</th><th>作用</th><th>来源</th></tr></thead><tbody><tr><td><code>/</code></td><td>调 Skills / 插件</td><td>Skills、Plugins、Scheduled Tasks</td></tr><tr><td><code>+</code></td><td>插件 / 上传 / 新项目</td><td>Plugins、Projects</td></tr><tr><td><code>/skill-creator</code></td><td>对话创建 Skill</td><td><a href="https://www.kimi.com/help/features/what-are-skills" target="_blank" rel="noreferrer">Skills</a></td></tr><tr><td><code>/stop</code></td><td>Claw 群聊强制打断</td><td><a href="https://www.kimi.com/help/kimi-claw/group-chat" target="_blank" rel="noreferrer">group-chat</a></td></tr><tr><td>Create scheduled task</td><td>侧栏建定时任务</td><td><a href="https://www.kimi.com/help/features/scheduled-tasks" target="_blank" rel="noreferrer">Scheduled Tasks</a></td></tr><tr><td>Create（Claw）</td><td>一键云端 OpenClaw</td><td><a href="https://www.kimi.com/en/help/kimi-claw/overview" target="_blank" rel="noreferrer">Claw overview</a></td></tr><tr><td>Link existing OpenClaw</td><td>接入自建实例</td><td>同上</td></tr><tr><td>Start Group Chat</td><td>Claw 群聊</td><td>group-chat</td></tr><tr><td>Settings → Personalization → Memory Space</td><td>管理记忆</td><td><a href="https://www.kimi.com/help/features/memory-space" target="_blank" rel="noreferrer">Memory</a></td></tr><tr><td>Settings → Chat channels</td><td>Claw 渠道</td><td>Claw overview</td></tr></tbody></table><p>官方技能名例子：<code>docx</code>、<code>deep-research</code>、<code>sop-writer</code>、<code>event-etf-study</code>。</p><h2 id="会员概览-乐理名-美元" tabindex="-1">会员概览（乐理名 + 美元） <a class="header-anchor" href="#会员概览-乐理名-美元" aria-label="Permalink to &quot;会员概览（乐理名 + 美元）&quot;">​</a></h2><p>来源：<a href="https://www.kimi.com/zh-hans/help/membership/membership-overview" target="_blank" rel="noreferrer">membership-overview</a>。聊天 <strong>K2.6 免费、不耗额度</strong>。会员功能共用水池。</p><p>第一张表：</p><table tabindex="0"><thead><tr><th>功能</th><th>Moderato $19/月</th><th>Allegretto $39/月</th><th>Allegro $99/月</th><th>Vivace $199/月</th></tr></thead><tbody><tr><td>Agent 额度*</td><td>60</td><td>150</td><td>360</td><td>720</td></tr><tr><td>Agent 并发任务数</td><td>2</td><td>2</td><td>4</td><td>4</td></tr><tr><td>Agent 速度优先级</td><td>4×</td><td>4×</td><td>4×</td><td>4×</td></tr><tr><td>专业数据库</td><td>2,000 次</td><td>5,000 次</td><td>12,000 次</td><td>24,000 次</td></tr><tr><td>Kimi Code</td><td>可调用</td><td>可调用</td><td>可调用</td><td>可调用</td></tr></tbody></table><p>* 官方脚注：按典型任务 token 估算的近似值，仅供参考。</p><p>第二张表（同页，摘与对话 / Agent 相关的行）：</p><table tabindex="0"><thead><tr><th>功能</th><th>Moderato</th><th>Allegretto</th><th>Allegro</th><th>Vivace</th></tr></thead><tbody><tr><td>K3 超长对话（最高 100 万 tokens）</td><td>—</td><td>—</td><td>✅</td><td>✅</td></tr><tr><td>定时任务</td><td>10</td><td>15</td><td>20</td><td>25</td></tr><tr><td>小组件任务</td><td>10</td><td>15</td><td>20</td><td>25</td></tr><tr><td>项目数</td><td>20</td><td>20</td><td>100</td><td>100</td></tr><tr><td>项目存储</td><td>20GB</td><td>20GB</td><td>50GB</td><td>50GB</td></tr><tr><td>插件</td><td>15+ 种</td><td>15+ 种</td><td>15+ 种</td><td>15+ 种</td></tr><tr><td>Agent Swarm</td><td>✅</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Swarm 并发子任务</td><td>2</td><td>4</td><td>8</td><td>8</td></tr><tr><td>目标模式</td><td>—</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Kimi Claw（网页 / 安卓 / PC）</td><td>—</td><td>✅</td><td>✅</td><td>✅</td></tr><tr><td>Claw 群聊</td><td>—</td><td>10</td><td>10</td><td>10</td></tr></tbody></table><p>年付：官方写每年最多可省 <strong>$480</strong>。Kimi Code 另有 <strong>5 小时 / 每周</strong> 速率限制。</p><h2 id="功能页上的另一套档位名" tabindex="-1">功能页上的另一套档位名 <a class="header-anchor" href="#功能页上的另一套档位名" aria-label="Permalink to &quot;功能页上的另一套档位名&quot;">​</a></h2><p><a href="https://www.kimi.com/help/features/project" target="_blank" rel="noreferrer">Projects</a> 与 <a href="https://www.kimi.com/help/features/scheduled-tasks" target="_blank" rel="noreferrer">Scheduled Tasks</a> 使用 <strong>Free / Go / Pro / Max / Ultra</strong>。官方<strong>没有</strong>把它们逐档等于 Moderato…。不要自己对齐。</p><p>Projects：</p><table tabindex="0"><thead><tr><th></th><th>Free</th><th>Go</th><th>Pro</th><th>Max</th><th>Ultra</th></tr></thead><tbody><tr><td>项目数</td><td>2</td><td>20</td><td>20</td><td>100</td><td>100</td></tr><tr><td>项目存储</td><td>500MB</td><td>20GB</td><td>20GB</td><td>50GB</td><td>50GB</td></tr></tbody></table><p>Scheduled Tasks（<strong>同时处于 active 的数量</strong>，创建总数不限）：</p><table tabindex="0"><thead><tr><th></th><th>Free</th><th>Go</th><th>Pro</th><th>Max</th><th>Ultra</th></tr></thead><tbody><tr><td>定时任务</td><td>2</td><td>6</td><td>15</td><td>20</td><td>25</td></tr></tbody></table><p>项目文件：每文件 ≤ <strong>100 MB</strong>，最多 <strong>50</strong> 个。</p><p>定时任务默认过期：Daily +7 天；Weekly +1 月；Monthly +3 月。</p><h2 id="其它硬数字-均有出处" tabindex="-1">其它硬数字（均有出处） <a class="header-anchor" href="#其它硬数字-均有出处" aria-label="Permalink to &quot;其它硬数字（均有出处）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>数字</th><th>出处</th></tr></thead><tbody><tr><td>Agent 20+ 工具</td><td>Agent 概览</td></tr><tr><td>Swarm 最多 300 子 Agent、&gt;4000 次工具调用、约 4.5×</td><td>Agent Swarm</td></tr><tr><td>Deep Research 万字 / 10,000+ word</td><td>Agent 概览</td></tr><tr><td>Sheets 最多 1,000 行 Excel</td><td>Agent 概览</td></tr><tr><td>ClawHub 5,000+ 技能</td><td>Agent 概览 / Claw 介绍</td></tr><tr><td>K3：2.8T 参数、1M token、原生视觉</td><td>Agent 概览（2026-07-16）</td></tr><tr><td>一键 Claw：Allegretto+；默认 K2.6</td><td>Claw overview</td></tr><tr><td>插件：K3 / K3 Swarm / Deep Research / Websites / PPT；Claw 与 Plus 不行</td><td>Plugins</td></tr></tbody></table><h2 id="高质量信息源" tabindex="-1">高质量信息源 <a class="header-anchor" href="#高质量信息源" aria-label="Permalink to &quot;高质量信息源&quot;">​</a></h2><p>最后核实：2026-08-19。只收亲自打开过的官方页。</p><h3 id="一手官方" tabindex="-1">一手官方 <a class="header-anchor" href="#一手官方" aria-label="Permalink to &quot;一手官方&quot;">​</a></h3><table tabindex="0"><thead><tr><th>来源</th><th>用途</th></tr></thead><tbody><tr><td><a href="https://www.kimi.com/" target="_blank" rel="noreferrer">kimi.com</a></td><td>工作台本体</td></tr><tr><td><a href="https://www.kimi.com/zh-cn/products/" target="_blank" rel="noreferrer">zh-cn/products</a></td><td>一级产品</td></tr><tr><td><a href="https://www.kimi.com/zh-hans/help" target="_blank" rel="noreferrer">zh-hans/help</a></td><td>中文帮助总目</td></tr><tr><td><a href="https://www.kimi.com/help" target="_blank" rel="noreferrer">help</a></td><td>英文帮助总目</td></tr><tr><td><a href="https://www.kimi.com/zh-cn/help/agent/agent-overview" target="_blank" rel="noreferrer">Agent 概览</a></td><td>Agent 步骤</td></tr><tr><td><a href="https://www.kimi.com/zh-hans/help/agent/agent-swarm" target="_blank" rel="noreferrer">Agent Swarm</a></td><td>Swarm</td></tr><tr><td><a href="https://www.kimi.com/zh-hans/help/membership/membership-overview" target="_blank" rel="noreferrer">会员概览</a></td><td>套餐与水池</td></tr><tr><td><a href="https://www.kimi.com/en/help/kimi-claw/overview" target="_blank" rel="noreferrer">Claw overview</a></td><td>部署</td></tr><tr><td><a href="https://www.kimi.com/help/kimi-claw/group-chat" target="_blank" rel="noreferrer">Claw 群聊</a></td><td>Conductor / <code>/stop</code></td></tr><tr><td><a href="https://www.kimi.com/help/features/project" target="_blank" rel="noreferrer">Projects</a></td><td>项目</td></tr><tr><td><a href="https://www.kimi.com/help/features/what-are-skills" target="_blank" rel="noreferrer">Skills</a></td><td>技能</td></tr><tr><td><a href="https://www.kimi.com/help/features/plugins" target="_blank" rel="noreferrer">Plugins</a></td><td>插件</td></tr><tr><td><a href="https://www.kimi.com/help/features/scheduled-tasks" target="_blank" rel="noreferrer">Scheduled Tasks</a></td><td>定时任务</td></tr><tr><td><a href="https://www.kimi.com/help/features/memory-space" target="_blank" rel="noreferrer">Memory</a></td><td>记忆</td></tr><tr><td><a href="https://www.kimi.com/help/kimi-work/overview" target="_blank" rel="noreferrer">Kimi Work overview</a></td><td>桌面端（本目录不展开）</td></tr><tr><td><a href="https://www.moonshot.cn/" target="_blank" rel="noreferrer">moonshot.cn</a></td><td>公司 / App</td></tr><tr><td><a href="https://platform.moonshot.cn/" target="_blank" rel="noreferrer">platform.moonshot.cn</a></td><td>API</td></tr></tbody></table><h3 id="访问提示" tabindex="-1">访问提示 <a class="header-anchor" href="#访问提示" aria-label="Permalink to &quot;访问提示&quot;">​</a></h3><p><code>www.kimi.com</code> 对部分自动化抓取会落到 198.18.x，命令行 GET 可能失败。帮助中心乱猜 slug 会进空搜索页。先打开分类页再抄链接。</p><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li><a href="./">学习地图</a></li><li><a href="./kimi.html">教程</a></li><li><a href="./kimi-cookbook.html">Cookbook</a></li><li><a href="./kimi-glossary.html">术语表</a></li></ul>',37)])])}const f=e(o,[["render",h]]);export{g as __pageData,f as default};
